"""Fail if a translatable string of the app has no translation in one of the shipped languages.

Usage: python check_translations.py <generated main.pot> <locale dir>
The .pot is generated by ``bench generate-pot-file --app rappen`` in CI, so it contains every string that
Frappe extracts from Python, JavaScript and doctype JSON. Every one of them needs a translation in de, fr
and it.
"""

import ast
import sys
from pathlib import Path

LANGUAGES = ("de", "fr", "it")


def read_catalog(path: Path) -> dict[str, str]:
	"""msgid to msgstr, for a simple .po or .pot file without plural forms or contexts."""
	entries: dict[str, str] = {}
	key, current = None, {"msgid": "", "msgstr": "", "msgctxt": ""}

	def flush():
		if current["msgid"]:
			entries[current["msgid"]] = current["msgstr"]

	for line in path.read_text(encoding="utf-8").splitlines():
		line = line.strip()
		if not line or line.startswith("#"):
			continue
		for keyword in ("msgctxt", "msgid", "msgstr"):
			if line.startswith(keyword + " "):
				if keyword in ("msgctxt", "msgid") and (current["msgstr"] or key == "msgstr"):
					flush()
					current = {"msgid": "", "msgstr": "", "msgctxt": ""}
				key = keyword
				current[key] = ast.literal_eval(line[len(keyword) + 1 :])
				break
		else:
			if line.startswith('"') and key:
				current[key] += ast.literal_eval(line)
	flush()
	return entries


def main() -> int:
	pot, locale = Path(sys.argv[1]), Path(sys.argv[2])
	wanted = sorted(read_catalog(pot))
	missing = 0
	for language in LANGUAGES:
		translated = read_catalog(locale / f"{language}.po")
		for msgid in wanted:
			if not translated.get(msgid):
				print(f"{language}: missing translation for {msgid!r}")
				missing += 1
	print(f"{len(wanted)} strings, {missing} translations missing")
	return 1 if missing else 0


if __name__ == "__main__":
	sys.exit(main())
